  membershipJoin: "<section class=\"inz-section\" style=\"background: linear-gradient(135deg, #160933 0%, #261866 60%, #61145f 100%); color: #ffffff; padding: clamp(4rem, 10vw, 6rem) 0; text-align: center;\">\r\n  <div class=\"inz-container\">\r\n    <h1 style=\"color: #ffffff; max-width: 20ch; margin-inline: auto;\">Become a member</h1>\r\n    <p style=\"color: #e8e6ee; max-width: 55ch; margin: 0 auto 1.5rem;\">Membership is managed through Member Jungle. Complete your application there and the team will be in touch.</p>\r\n    <a href=\"https://inzbc.memberjungle.club\" class=\"inz-btn inz-btn--primary\">Apply via Member Jungle</a>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"inz-section\" style=\"background-color: #ffffff; padding: clamp(3rem, 6vw, 4.5rem) 0;\">\r\n  <div class=\"inz-container\" style=\"max-width: 76ch;\">\r\n    <h2>What happens next</h2>\r\n    <ol style=\"padding-left: 1.25rem; margin-bottom: 1.5rem;\">\r\n      <li style=\"margin-bottom: 0.75rem;\">Select the tier that matches your organisation.</li>\r\n      <li style=\"margin-bottom: 0.75rem;\">Submit the application through Member Jungle.</li>\r\n      <li style=\"margin-bottom: 0.75rem;\">The INZBC secretariat reviews and confirms your membership.</li>\r\n      <li>You receive access to member events, intelligence and the member directory.</li>\r\n    </ol>\r\n    <p>Questions? <a href=\"/connect\" style=\"color: #61145f; text-decoration: underline;\">Contact the secretariat</a>.</p>\r\n  </div>\r\n</section>",
