  newsletters: "<section class=\"inz-section\" style=\"background: linear-gradient(135deg, #160933 0%, #261866 60%, #61145f 100%); color: #ffffff; padding: clamp(4rem, 10vw, 6rem) 0; text-align: center;\">\r\n  <div class=\"inz-container\">\r\n    <h1 style=\"color: #ffffff; max-width: 18ch; margin-inline: auto;\">Newsletters</h1>\r\n    <p style=\"color: #e8e6ee; max-width: 55ch; margin: 0 auto;\">Kia Ora India, the monthly newsletter archive, and the Trade Intelligence Digest.</p>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"inz-section\" style=\"background-color: #ffffff; padding: clamp(3rem, 6vw, 4.5rem) 0;\">\r\n  <div class=\"inz-container\">\r\n    <h2>Kia Ora India</h2>\r\n    <p>[[The site currently describes Kia Ora India as quarterly with a December 2023 \"latest\" issue. Confirm current cadence and latest issue with INZBC before publish.]]</p>\r\n\r\n    <h2 style=\"margin-top: 2.5rem;\">Trade Intelligence Digest</h2>\r\n    <p>Weekly, LLM-summarised, human-reviewed digest of India–NZ trade news. Renders only items with CMS status = published.</p>\r\n    <a href=\"#\" class=\"inz-btn inz-btn--primary\" style=\"margin-top: 1rem;\">Browse the archive</a>\r\n\r\n    <h2 style=\"margin-top: 2.5rem;\">Monthly newsletter archive</h2>\r\n    <p>[[Confirm Mailchimp vs eocampaign hosting. Link to archive.]]</p>\r\n  </div>\r\n</section>",
  news: "<section class=\"inz-section\" style=\"background: linear-gradient(135deg, #160933 0%, #261866 60%, #61145f 100%); color: #ffffff; padding: clamp(4rem, 10vw, 6rem) 0; text-align: center;\">\r\n  <div class=\"inz-container\">\r\n    <h1 style=\"color: #ffffff; max-width: 18ch; margin-inline: auto;\">News</h1>\r\n    <p style=\"color: #e8e6ee; max-width: 55ch; margin: 0 auto;\">Updates from INZBC and the NZ–India trade relationship.</p>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"inz-section\" style=\"background-color: #ffffff; padding: clamp(3rem, 6vw, 4.5rem) 0;\">\r\n  <div class=\"inz-container\">\r\n    <p>[[This page is the blog root. Connect the Wix Blog app here, or list recent posts manually until the CMS is set up.]]</p>\r\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr)); gap: 1.5rem; margin-top: 2rem;\">\r\n      <article style=\"padding: 1.5rem; background: #f6f5f8; border-radius: 10px;\">\r\n        <p style=\"font-family: 'Big Shoulders', Impact, sans-serif; text-transform: uppercase; color: #f05b29; margin: 0 0 0.5rem;\">[[Date]]</p>\r\n        <h3 style=\"font-size: 1.35rem;\">[[Post title]]</h3>\r\n        <p style=\"margin: 0 0 1rem;\">[[Excerpt]]</p>\r\n        <a href=\"#\" class=\"inz-btn inz-btn--primary\" style=\"padding: 0.6em 1.2em; font-size: 0.875rem;\">Read more</a>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>",
